@@ -0,0 +1,73 @@
+var url = require('url');
+
+// Only these methods are considered state-changing and thus need protection.
+var UNSAFE_METHODS = {
+  POST: true,
+  PUT: true,
+  DELETE: true,
+  PATCH: true
+};
+
+function getHost(value) {
+  if (!value || typeof value !== 'string') {
+    return null;
+  }
+  try {
+    // Referer is a full URL, Origin is scheme://host[:port]
+    var parsed = url.parse(value);
+    return parsed.host || null;
+  } catch (e) {
+    return null;
+  }
+}
+
+/**
+ * Verify that a request targeting the whistle web UI / API is same-origin.
+ *
+ * This prevents CSRF: a malicious web page cannot set the Origin/Referer
+ * headers to whistle's own host, so cross-site requests are rejected.
+ */
+function isSameOrigin(req) {
+  var headers = req.headers || {};
+  var host = headers.host;
+  if (!host) {
+    return false;
+  }
+  var origin = headers.origin;
+  var referer = headers.referer || headers.referrer;
+
+  // If neither Origin nor Referer is present, this is not a
+  // browser cross-site request (e.g. curl / server-side call).
+  if (!origin && !referer) {
+    return true;
+  }
+
+  var sourceHost = getHost(origin) || getHost(referer);
+  if (!sourceHost) {
+    return false;
+  }
+  return sourceHost === host;
+}
+
+module.exports = function csrf(req, res, next) {
+  var method = (req.method || 'GET').toUpperCase();
+
+  // Safe methods do not change state; allow them through.
+  if (!UNSAFE_METHODS[method]) {
+    return next();
+  }
+
+  if (isSameOrigin(req)) {
+    return next();
+  }
+
+  res.statusCode = 403;
+  res.setHeader('Content-Type', 'text/plain; charset=utf-8');
+  res.end('Forbidden: cross-site request blocked (CSRF protection)');
+};
+
+module.exports.isSameOrigin = isSameOrigin;
